('MICL Aaradhya OnePark', 'micl-aaradhya-onepark', '60ft Road, Ghatkopar East', '₹ 2.80 Cr', 'new-launch', 'https://images.unsplash.com/photo-1545324418-cc1a3fa10c00?w=1200&q=80', '3, 4 & 5 BHK', 'Dec 2026', 'P51800000001', 'Residential', 'Ultra Luxury on 60ft Road', '["https://images.unsplash.com/photo-1600596542815-ffad4c1539a9?w=1200&q=80", "https://images.unsplash.com/photo-1600047509807-ba8f99d2cdde?w=1200&q=80", "https://images.unsplash.com/photo-1600585154340-be6161a56a0c?w=1200&q=80", "https://images.unsplash.com/photo-1600566753190-17f0baa2a6c3?w=1200&q=80"]', '["Rooftop Infinity Pool", "State-of-the-art Gym", "Zen Garden & Yoga Deck", "Automated Parking System"]', '["Swimming Pool", "Gym", "Concierge", "Security"]', 'Aaradhya OnePark brings ultra-luxury living to the prestigious 60ft Road in Ghatkopar East. A perfect blend of contemporary architecture and timeless elegance.', true),
('Shubham Elegance', 'shubham-elegance-ghatkopar', 'Ghatkopar East, Mumbai', '₹ 1.95 Cr', 'ready-to-move', 'https://images.unsplash.com/photo-1512917774080-9991f1c4c750?w=1200&q=80', '2 & 3 BHK', 'Ready to Move', 'P51800000002', 'Residential', 'Premium Ready Homes', '["https://images.unsplash.com/photo-1600573472591-ee6b68d14c68?w=1200&q=80", "https://images.unsplash.com/photo-1600210492486-724fe5c67fb0?w=1200&q=80", "https://images.unsplash.com/photo-1598928506311-c55dd1b31043?w=1200&q=80", "https://images.unsplash.com/photo-1599423300746-b62533397364?w=1200&q=80"]', '["Grand Entrance Lobby", "Indoor Games Room", "Landscaped Podium", "Vaastu Compliant"]', '["Security", "Play Area", "Garden"]', 'Shubham Elegance offers premium ready-to-move-in residences in the heart of Ghatkopar East, providing excellent connectivity to key transit points and premium social infrastructure.', true),
('Happy Home Heights', 'happy-home-heights', 'Garodia Nagar, Ghatkopar East', '₹ 1.85 Cr', 'premium', 'https://images.unsplash.com/photo-1600607687920-4e2a09cf159d?w=1200&q=80', '2 & 3 BHK', 'Mid 2025', 'P51800000003', 'Residential', 'Smart Homes in Garodia Nagar', '["https://images.unsplash.com/photo-1502005229762-cf1b2da7c5d6?w=1200&q=80", "https://images.unsplash.com/photo-1522708323590-d24dbb6b0267?w=1200&q=80", "https://images.unsplash.com/photo-1502672260266-1c1de2d96674?w=1200&q=80", "https://images.unsplash.com/photo-1497366216548-37526070297c?w=1200&q=80"]', '["Smart Home Automation", "Terrace Garden", "Children\'s Play Area", "Advanced Fire Safety"]', '["Gym", "Kids Play Area", "Smart Security"]', 'Experience modern living with smart home automation at Happy Home Heights. Situated in the peaceful enclave of Garodia Nagar, ensuring serenity amidst city life.', true),
('Ajmera Manhattan', 'ajmera-manhattan', 'Ghatkopar East, Mumbai', '₹ 2.20 Cr', 'upcoming', 'https://images.unsplash.com/photo-1600585154526-990dced4db0d?w=1200&q=80', '2, 3 & 4 BHK', 'Jan 2027', 'P51800000004', 'Residential', 'New York Lifestyle in Mumbai', '["https://images.unsplash.com/photo-1560448204-e02f11c3d0e2?w=1200&q=80", "https://images.unsplash.com/photo-1564013799919-ab600027ffc6?w=1200&q=80", "https://images.unsplash.com/photo-1560185007-cde436f6a4d0?w=1200&q=80", "https://images.unsplash.com/photo-1583847268964-b28dc8f51f92?w=1200&q=80"]', '["Olympic Length Pool", "Grand Clubhouse", "Private Theatre", "Business Center"]', '["Swimming Pool", "Theatre", "Gym", "Lounge"]', 'Bringing the New York lifestyle to Ghatkopar. Ajmera Manhattan offers a premium living experience with expansive layouts and world-class leisure facilities.', true),
('Silver Harmony', 'silver-group-harmony', 'Ghatkopar East, Mumbai', '₹ 2.50 Cr', 'ready-to-move', 'https://images.unsplash.com/photo-1613490900233-141c5560d75d?w=1200&q=80', '3 & 4 BHK', 'Ready to Move', 'P51800000005', 'Residential', 'Architectural Brilliance', '["https://images.unsplash.com/photo-1502672023488-70e25813eb80?w=1200&q=80", "https://images.unsplash.com/photo-1554995207-c18c203602cb?w=1200&q=80", "https://images.unsplash.com/photo-1616137466211-f939a420be84?w=1200&q=80", "https://images.unsplash.com/photo-1618219908412-a29a1bb7b86e?w=1200&q=80"]', '["Double Height Lobby", "Italian Marble Flooring", "Senior Citizens Corner", "EV Charging Stations"]', '["Lobby", "Garden", "Parking"]', 'Silver Harmony stands as a testament to architectural brilliance. Enjoy spacious living with premium fittings, zero space wastage, and excellent cross-ventilation.', true),
